import{_ as t,o as l,c as a,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"200 Clusters vs 1 Admin - Bartosz Rabiega, OVH","description":"","frontmatter":{"title":"200 Clusters vs 1 Admin - Bartosz Rabiega, OVH","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","分布式存储","自动化运维","OVH","软件定义存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/200_Clusters_vs_1_Admin_-_Bartosz_Rabiega_OVH.md","filePath":"posts/2019/200_Clusters_vs_1_Admin_-_Bartosz_Rabiega_OVH.md","lastUpdated":1780459816000}'),i={name:"posts/2019/200_Clusters_vs_1_Admin_-_Bartosz_Rabiega_OVH.md"};function r(o,s,n,_,g,p){return l(),a("div",null,[...s[0]||(s[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年（具体日期未提及）</p><p><strong>与会人员</strong>： Bartosz La Vega（OVH Poland DevOps工程师）</p><p><strong>会议主题</strong>： OVH在Ceph分布式存储系统（Safe）的部署、管理和维护经验分享</p><p><strong>会议内容</strong>：</p><p><strong>一、背景介绍</strong></p><ul><li>Bartosz La Vega介绍了自己的背景，自2016年起在OVH担任DevOps工程师，负责Safe as a Service团队，提供管理的Safe集群服务。</li><li>OVH是欧洲最大的云服务提供商之一，拥有26个数据中心，采用水冷技术，服务器容量超过100万台。</li></ul><p><strong>二、Safe在OVH的应用</strong></p><ul><li>Safe主要用于OVH的公共云服务，提供额外的块存储服务。</li><li>OVH还提供名为“云磁盘阵列”的产品，为外部客户提供专用Safe集群。</li></ul><p><strong>三、Safe集群规模</strong></p><ul><li>OVH目前拥有超过50PB的Safe存储空间，分布在210个集群中，集群规模从小型到大型不等。</li></ul><p><strong>四、Safe集群设计目标</strong></p><ul><li>无单点故障</li><li>最大化性能，最小化成本</li><li>对硬件资源有良好的控制</li><li>易于部署、升级和管理</li></ul><p><strong>五、实现设计目标的方法</strong></p><ul><li><strong>无单点故障</strong>： 采用三副本机制和DC拓扑结构，确保数据安全。</li><li><strong>性能优化</strong>： 使用FlashCache和NVMe加速HDD驱动器，提高I/O性能。</li><li><strong>资源隔离</strong>： 使用Macvlan技术提供不同的网络接口，以及容器技术进行资源隔离和分配。</li></ul><p><strong>六、集群管理</strong></p><ul><li><strong>自动化控制平面</strong>： 开发了一个自动化控制平面，用于管理集群配置、容器的创建和升级、集群的扩展和缩减等操作。</li><li><strong>远程API</strong>： 为客户提供远程API，以便管理自己的Safe集群。</li><li><strong>维护操作</strong>： 利用Apache Airflow等开源项目，实现集群的自动维护操作，如磁盘替换、NVMe预测性维护等。</li></ul><p><strong>七、总结</strong></p><ul><li>OVH通过开发自动化控制平面和集成监控解决方案，实现了对Safe集群的高效管理和维护。</li><li>单个系统管理员能够管理超过200个Safe集群，大大提高了运维效率。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续优化控制平面，增加更多功能，如监控、自愈等。</li><li>计划升级Safe集群到Luminous版本。</li><li>探索更多自动化和智能化运维技术。</li></ul><p><strong>改进点</strong>：</p><ol><li>修正了原总结中部分遗漏的信息，如Safe集群的规模和设计目标。</li><li>添加了对自动化控制平面的详细描述，包括其功能和管理方式。</li><li>增加了后续行动计划的内容。</li></ol>',23)])])}const f=t(i,[["render",r]]);export{d as __pageData,f as default};
